     #[cfg(all(feature = "std", not(target_family = "wasm")))]
     pub fn set_blocking(&self, value: T) -> Result<&T, T> {
         let mut value = Some(value);
         self.get_or_init_blocking(|| value.take().unwrap());

         match value {
             Some(value) => Err(value),
             None => {
